"""Post-primary correctness checks and finite-support exact-tail verification."""
import itertools,json,sys
from collections import defaultdict
from pathlib import Path
ROOT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT.parent/'edge-multirow'))
import verify as oracle
import run as search
PLAN={'phase':'Specified after primary expanded results; independent correctness and exact-tail verification only.',
      'oracle':'Compare full solution sets on every added-page block using row permutations and column-count join.',
      'exact_tail':'For each pooled edition with complete support <=4096, enumerate every global layout and calculate upper-tail fraction, including observed ties. Do not override failed frozen support or mobility gates.',
      'witness_followup':'Report the literal f54r lines9/10/11 in ZL/IT for descriptive transcription comparison. Do not alter row grouping or the original fact specification.'}

def exact(pages):
    ts=search.dsl.tokens(pages);rows=defaultdict(list)
    for i,t in enumerate(ts):
        if t['unit']=='P':rows[t['line']].append(i)
    blocks=defaultdict(list)
    for row in rows.values():
        row.sort(key=lambda i:ts[i]['k']);blocks[(ts[row[0]]['page'],ts[row[0]]['n'])].append(row)
    active=[];support=1
    for key,rs in sorted(blocks.items()):
        original=[[ts[i]['w'] for i in row] for row in rs];e=search.enumerate_block(original);assert e['complete']
        support*=len(e['layouts'])
        if len(e['layouts'])>1:active.append((rs,e['layouts']))
    assert support<=4096
    sel={'unit':['P'],'certain':True};stat={'edge_length_cmi':True}
    obs=search.dsl.statistic(stat,search.dsl.select(ts,sel),ts);values=[]
    for combination in itertools.product(*(layouts for rs,layouts in active)):
        words=[t['w'] for t in ts]
        for (rs,layouts),layout in zip(active,combination):
            n=len(rs[0])
            for r,row in enumerate(rs):
                for k,i in enumerate(row):words[i]=layout[r*n+k]
            search.check_layout(tuple(ts[i]['w'] for row in rs for i in row),layout,n)
        sh=[dict(t,w=w) for t,w in zip(ts,words)]
        values.append(search.dsl.statistic(stat,search.dsl.select(sh,sel),sh))
    assert len(values)==support and any(v==obs for v in values)
    return {'layouts':support,'observed_bits':obs,'upper_tail_count':sum(v>=obs for v in values),
            'exact_upper_tail':sum(v>=obs for v in values)/support,'smallest_possible_exact_tail':1/support,
            'minimum':min(values),'maximum':max(values),'values':sorted(values)}

if __name__=='__main__':
    (ROOT/'verification-plan.json').write_text(json.dumps(PLAN,indent=2)+'\n',encoding='utf-8')
    out={'plan':PLAN,'results':{}}
    for ed in ('zl','it'):
        added,prior=search.corpus.split_pages('practice',ed)
        o=oracle.check(added);e=exact(list(search.corpus.pages(ed)))
        witness_page=next(p for p in search.corpus.pages(ed) if p.id=='f54r')
        lines=[{'id':ln.id,'n':len(ln.words),'words':ln.words} for ln in witness_page.lines if ln.n in (9,10,11)]
        out['results'][ed]={'added_oracle':o,'pooled_exact':e,'witness_transcription':lines}
        print(ed,'added oracle',{k:v for k,v in o.items() if k!='blocks'},flush=True)
        print(ed,'exact',{k:v for k,v in e.items() if k!='values'},flush=True)
        print(ed,'witness',lines,flush=True)
        (ROOT/'verification.json').write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8')

